     1	export interface Page<T> {
     2	  items: T[];
     3	  page: number;
     4	  pageSize: number;
     5	  total: number;
     6	  hasNext: boolean;
     7	}
     8	
     9	export function paginate<T>(all: T[], page: number, pageSize: number): Page<T> {
    10	  const size = Math.max(1, Math.floor(pageSize));
    11	  const p = Math.max(1, Math.floor(page));
    12	  const start = (p - 1) * size;
    13	  const items = all.slice(start, start + size);
    14	  return { items, page: p, pageSize: size, total: all.length, hasNext: start + size < all.length };
    15	}
    16	
    17	/** Stable multi-key sort. Each key returns a number or string; ties fall through to the next key. */
    18	export function sortBy<T>(items: T[], ...keys: ((t: T) => number | string)[]): T[] {
    19	  return items
    20	    .map((item, index) => ({ item, index }))
    21	    .sort((a, b) => {
    22	      for (const key of keys) {
    23	        const ka = key(a.item);
    24	        const kb = key(b.item);
    25	        if (ka < kb) return -1;
    26	        if (ka > kb) return 1;
    27	      }
    28	      return a.index - b.index;
    29	    })
    30	    .map((x) => x.item);
    31	}

